const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Thailand geometry using LSIB simplified
  var thailand = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_co', 'TH'));

  // Simplify geometry to avoid computation issues
  var thailandGeom = thailand.geometry().simplify(1000);

  // 2. Define time periods
  var febStart = '2008-02-01';
  var febEnd = '2008-02-29';
  var augStart = '2008-08-01';
  var augEnd = '2008-08-31';

  // 3. Get MODIS Terra fire data (MOD14A1)
  var febCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(febStart, febEnd)
    .filterBounds(thailandGeom);

  var augCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(augStart, augEnd)
    .filterBounds(thailandGeom);

  // 4. Check collection sizes
  var febSize = febCollection.size().getInfo();
  var augSize = augCollection.size().getInfo();

  console.log('February 2008 Images:', febSize);
  console.log('August 2008 Images:', augSize);

  // Case C1: Empty collection
  if (febSize === 0 || augSize === 0) {
    // Try Aqua MODIS as fallback
    console.log('Trying Aqua MODIS as fallback...');
    var febCollectionAqua = ee.ImageCollection('MODIS/006/MYD14A1')
      .filterDate(febStart, febEnd)
      .filterBounds(thailandGeom);
    var augCollectionAqua = ee.ImageCollection('MODIS/006/MYD14A1')
      .filterDate(augStart, augEnd)
      .filterBounds(thailandGeom);

    febSize = febCollectionAqua.size().getInfo();
    augSize = augCollectionAqua.size().getInfo();

    console.log('Aqua February 2008 Images:', febSize);
    console.log('Aqua August 2008 Images:', augSize);

    if (febSize === 0 || augSize === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
    // Use Aqua collections
    febCollection = febCollectionAqua;
    augCollection = augCollectionAqua;
  }

  // 5. Function to count fire pixels in an image
  function countFirePixels(img) {
    // FireMask: 0=not processed, 1-3=cloud/water, 4=non-fire, 5-7=fire, 8=missing, 9=sea
    var fireMask = img.select('FireMask');
    // Create binary fire mask (5,6,7 = fire)
    var fireBinary = fireMask.gte(5).and(fireMask.lte(7));
    // Count fire pixels
    var count = fireBinary.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: thailandGeom,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    }).get('FireMask');
    return ee.Image.constant(count).rename('fireCount');
  }

  // 6. Compute total fire counts for each month
  var febFireCountImg = febCollection.map(countFirePixels).sum();
  var augFireCountImg = augCollection.map(countFirePixels).sum();

  var febFireCount = febFireCountImg.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: thailandGeom,
    scale: 1000,
    maxPixels: 1e9,
    bestEffort: true
  }).get('fireCount').getInfo();

  var augFireCount = augFireCountImg.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: thailandGeom,
    scale: 1000,
    maxPixels: 1e9,
    bestEffort: true
  }).get('fireCount').getInfo();

  console.log('February 2008 Fire Pixel Count:', febFireCount);
  console.log('August 2008 Fire Pixel Count:', augFireCount);

  // 7. Validation checks
  // Case C2: No valid fire pixels
  if ((febFireCount === 0 && augFireCount === 0) || 
      (febFireCount === null && augFireCount === null)) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Case C3: Calculation failure
  if (febFireCount === null || augFireCount === null || 
      isNaN(febFireCount) || isNaN(augFireCount) ||
      febFireCount === undefined || augFireCount === undefined) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare and output result
  console.log('Comparison: August > February?', augFireCount > febFireCount);

  if (augFireCount > febFireCount) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
